  def lookup(self, ctx, block_hashes):
    return self._nixl_client.lookup_tokens(block_hashes)

  def load(self, ctx, target_block_ids, device_tensors):
    return self._nixl_client.read_blocks(target_block_ids)

  def save(self, block_ids, block_hashes):
    self._pending.extend(zip(block_ids, block_hashes))

  def flush(self):
    self._nixl_client.write_blocks(self._pending)
    self._pending.clear()

  def sync(self):
    self._nixl_client.sync()
